create extension if not exists pgcrypto;
create table if not exists profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,role text not null default 'STAFF' check(role in('SUPER_ADMIN','ADMIN','STAFF')),phone text,avatar_url text,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists job_categories(id uuid primary key default gen_random_uuid(),name_en text not null,name_bn text not null,slug text unique not null,icon text,is_active boolean default true,created_at timestamptz default now());
create table if not exists countries(id uuid primary key default gen_random_uuid(),name_en text not null,name_bn text not null,iso_code text not null,flag_url text,description_bn text,is_active boolean default true,created_at timestamptz default now());
create table if not exists jobs(id uuid primary key default gen_random_uuid(),title_bn text not null,country_id uuid references countries(id),location_bn text,category_id uuid references job_categories(id),skill_level text not null check(skill_level in('skilled','semi-skilled','unskilled')),vacancies int,salary numeric,currency text,accommodation_bn text,food_bn text,working_hours_bn text,experience_bn text,education_bn text,gender_requirement text,age_requirement text,required_documents text[],description_bn text,application_deadline timestamptz,status text default 'draft' check(status in('draft','published','archived')),is_featured boolean default false,created_by uuid references profiles(id),created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists candidates(id uuid primary key default gen_random_uuid(),full_name text not null,mobile text not null,whatsapp text,email text not null,date_of_birth date,address text,district text,state text,passport_status text check(passport_status in('yes','no','processing')),passport_number text,education text,work_experience text,skills text[],preferred_country_id uuid references countries(id),preferred_category_id uuid references job_categories(id),resume_url text,additional_info text,status text default 'new' check(status in('new','reviewing','interviewed','shortlisted','hired','rejected')),created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists applications(id uuid primary key default gen_random_uuid(),job_id uuid references jobs(id) on delete cascade,candidate_id uuid references candidates(id) on delete cascade,status text default 'pending' check(status in('pending','under_review','shortlisted','interviewed','offered','hired','rejected')),notes text,created_at timestamptz default now(),updated_at timestamptz default now(),unique(job_id,candidate_id));
create table if not exists client_requirements(id uuid primary key default gen_random_uuid(),company_name text,contact_person text,mobile text,email text,country text,job_position text,workers_needed int,skills_required text,experience_required text,salary_range text,accommodation_required text,joining_date date,additional_requirements text,attachment_url text,status text default 'pending' check(status in('pending','contacted','in_progress','completed','cancelled')),assigned_to uuid references profiles(id),created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists client_requirement_notes(id uuid primary key default gen_random_uuid(),client_requirement_id uuid references client_requirements(id) on delete cascade,user_id uuid references profiles(id),note text,created_at timestamptz default now());
create table if not exists contact_queries(id uuid primary key default gen_random_uuid(),name text,email text,phone text,subject text,message text,status text default 'new' check(status in('new','read','resolved')),created_at timestamptz default now());
create table if not exists faqs(id uuid primary key default gen_random_uuid(),question_bn text,answer_bn text,"order" int default 0,is_active boolean default true,created_at timestamptz default now());
create table if not exists site_settings(id uuid primary key default gen_random_uuid(),key text unique,value jsonb,updated_at timestamptz default now());
create table if not exists activity_logs(id uuid primary key default gen_random_uuid(),user_id uuid references profiles(id),action text,details jsonb,created_at timestamptz default now());
create index if not exists jobs_status_idx on jobs(status);create index if not exists jobs_country_idx on jobs(country_id);create index if not exists jobs_category_idx on jobs(category_id);create index if not exists candidates_status_idx on candidates(status);create index if not exists applications_status_idx on applications(status);create index if not exists requirements_status_idx on client_requirements(status);create index if not exists logs_created_idx on activity_logs(created_at);
create or replace function is_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from profiles where id=auth.uid() and role in('SUPER_ADMIN','ADMIN','STAFF'))$$;
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['profiles','jobs','candidates','applications','client_requirements','site_settings'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t); END LOOP;END$$;
alter table job_categories enable row level security;alter table countries enable row level security;alter table client_requirement_notes enable row level security;alter table contact_queries enable row level security;alter table faqs enable row level security;alter table activity_logs enable row level security;
create policy profiles_admin on profiles for all using(is_admin()) with check(is_admin());create policy categories_admin on job_categories for all using(is_admin()) with check(is_admin());create policy countries_public on countries for select using(is_active=true or is_admin());create policy countries_admin on countries for all using(is_admin()) with check(is_admin());create policy jobs_public on jobs for select using((status='published' and (application_deadline is null or application_deadline>now())) or is_admin());create policy jobs_admin on jobs for all using(is_admin()) with check(is_admin());create policy candidates_insert on candidates for insert with check(status='new');create policy candidates_admin on candidates for all using(is_admin()) with check(is_admin());create policy applications_insert on applications for insert with check(status='pending');create policy applications_admin on applications for all using(is_admin()) with check(is_admin());create policy req_insert on client_requirements for insert with check(status='pending');create policy req_admin on client_requirements for all using(is_admin()) with check(is_admin());create policy notes_admin on client_requirement_notes for all using(is_admin()) with check(is_admin());create policy contact_insert on contact_queries for insert with check(status='new');create policy contact_admin on contact_queries for all using(is_admin()) with check(is_admin());create policy faq_public on faqs for select using(is_active=true or is_admin());create policy faq_admin on faqs for all using(is_admin()) with check(is_admin());create policy settings_admin on site_settings for all using(is_admin()) with check(is_admin());create policy logs_admin on activity_logs for all using(is_admin()) with check(is_admin());
